//@ compile-flags: -O
macro_rules! return_table {
    ($($route:literal => ($yes:literal, $no:literal)),* $(,)?) => {
        #[inline(never)]
        fn select(route: u16, bit: bool) -> u16 {
            match route {
                $($route => if bit { $yes } else { $no },)*
                _ => 999,
            }
        }

        fn main() {
            let expected: &[(u16, u16)] = &[$(($yes, $no)),*];
            for (route, &(yes, no)) in expected.iter().enumerate() {
                assert_eq!(select(std::hint::black_box(route as u16), true), yes);
                assert_eq!(select(std::hint::black_box(route as u16), false), no);
            }
            assert_eq!(select(2000, true), 999);
            assert_eq!(select(2000, false), 999);
        }
    };
}

